A_4U = 0.02; %m^2
m_4U = 6; %kg
I_4U = 0.12; %kg.m^2
Kp = 0.1; %gain of Proportional controller in N.m/rad
Kd = 0.2; %damping gain in N.m.s/rad - how strongly fast changes are resisted/damped 

theta0 = 0; omega0 = 0; torque0 = 0;
target_theta = 0.52;

params.A_6U=A_4U; params.m_6U=m_4U; params.I=I_4U; params.Kp=Kp; params.Kd=Kd;
params.theta0 = theta0; params.omega0 = omega0; params.tau0 = torque0;
params.t_theta = target_theta;

tspan = [0 60];
Y0 = [params.theta0; params.omega0];

opts = odeset('RelTol',1e-6,'AbsTol',1e-9);
[t,st] = ode45(@(t,st) rotational_motion(t,st,params), tspan, Y0, opts); %St are states

figure; %[output:1c54daee]
plot(t,st(:,1)) %[output:1c54daee]
xlabel("Time (s)"); ylabel("Angle \theta (rad)"); %[output:1c54daee]
yline(target_theta,'r--');  legend("\theta","Target Angle = 0.52 rad",'Location', 'southeast'); %[output:1c54daee]
figure; %[output:13a77e25]
plot(t,st(:,2),'r') %[output:13a77e25]
xlabel("Time (s)"); ylabel("Angular Velocity \omega (rad/s)"); legend("\omega") %[output:13a77e25]
w_n = sqrt(Kp/I_4U) %[output:247f43e8]
damp_ratio = Kd/(2*sqrt(I_4U*Kp)) %[output:43784a3b]

% time from 10% to 90% of target angle reached
% rise time

idx90 = find(st(:,1) >= 0.9*target_theta, 1, 'first');
if ~isempty(idx90) %[output:group:82f4e85c]
    fprintf('90%% reached at t = %.3f s\n', t(idx90)); %[output:44a764aa]
end %[output:group:82f4e85c]
idx10 = find(st(:,1) >= 0.1*target_theta, 1, 'first');
if ~isempty(idx10) %[output:group:5ff25408]
    fprintf('10%% reached at t = %.3f s\n', t(idx10)); %[output:8144000a]
end %[output:group:5ff25408]
if ~isempty(idx90) && ~isempty(idx10) %[output:group:879c8b6d]
    t_rise = t(idx90)-t(idx10); fprintf('Rise time: %.3f s\n', t_rise); %[output:23ed817a]
else 
    t_rise = NaN;
    fprintf('Rise time: not reached within simulation.\n');
end %[output:group:879c8b6d]

% Overshoot percentage relative to the target angle
peakTheta = max(st(:,1));
overshootPercent = max(0, (peakTheta - target_theta) / abs(target_theta) * 100);
fprintf('Overshoot: %.2f%%\n', overshootPercent); %[output:9e9d9efa]

% Settling time: first time after which the response remains within 2% of target
settlingBand = 0.02 * abs(target_theta);
outsideBand = abs(st(:,1) - target_theta) > settlingBand;
last = find(outsideBand, 1, 'last');
if isempty(last) %[output:group:68aff1a8]
    settlingTime = t(1);
elseif last == numel(t)
        settlingTime = NaN;
        fprintf('Settling time: not reached within simulation.\n');
else 
    settlingTime = t(last + 1);
    fprintf('Settling time: %.3f s\n', settlingTime); %[output:61470a91]
end %[output:group:68aff1a8]

% Steady-state error
steadyStateError = abs(target_theta - st(end,1));
fprintf('Steady-state error: %.3f rad\n', steadyStateError); %[output:57578ff5]


%table
newRow = table(Kp, Kd, damp_ratio, t_rise, overshootPercent, settlingTime, steadyStateError, ...
'VariableNames', {'Kp', 'Kd', 'DampingRatio', 'RiseTime(s)', 'Overshoot(%)', 'SettlingTime(s)', 'Steady-State error(rad)'});
allResults = [allResults; newRow];
disp(allResults) %[output:4168be07]

function domegadt = rotational_motion(t,st,params)

theta=st(1); omega=st(2); tau_d = -params.Kd*omega; %damping force
tau=params.Kp*(params.t_theta-theta)+tau_d;
dtheta=omega;
domega = tau / params.I;
domegadt=[dtheta; domega];
end

%P controller: used to modify torque at each instant to reach a target
%angle, where error = target angle - current angle
%gain (Kp): how strongly the P controller affects torque - constant

